public class PaymentConfig {
    @NotBlank private String apiKey;
    @Positive private int timeoutSeconds = 30;
    @Valid private RetryConfig retry;

    @Data
    public static class RetryConfig {
        private int maxAttempts = 3;
        @Min(100) private long backoffMs = 500;
    }
}

// application.yml
app:
  payment:
    api-key: ${PAYMENT_API_KEY}  # from env var
    timeout-seconds: 10
    retry:
      max-attempts: 5
